import { UseQueryOptions, queryOptions } from "@tanstack/react-query";

export async function fetchCoins() {
  const response = await fetch("https://api.coinpaprika.com/v1/coins");
  const data: ICoinData[] = await response.json();
  return data.slice(0, 100);
}

export async function fetchCoin(coinId: string) {
  const response = await fetch(
    `https://api.coinpaprika.com/v1/coins/${coinId}`,
  );
  if (!response.ok) {
    throw new Error("Coin Not Found");
  }
  const data: ICoinDetail = await response.json();
  return data;
}

export async function fetchCoinHistory(coinId: string) {
  const response = await fetch(
    `https://ohlcv-api.nomadcoders.workers.dev?coinId=${coinId}`,
  );
  if (!response.ok) {
    throw new Error(`History of ${coinId} Not Found`);
  }
  const data = await response.json();
  return data;
}

export const queryCoins = queryOptions({
  queryKey: ["Coins"],
  queryFn: fetchCoins,
  staleTime: Infinity,
});

export const queryCoin = (coinId?: string): UseQueryOptions<ICoinDetail> => ({
  queryKey: ["Coin", coinId],
  queryFn: () => fetchCoin(coinId!),
  enabled: Boolean(coinId),
});

export const queryCoinHistory = (
  coinId?: string,
): UseQueryOptions<ICoinHistory[]> => ({
  queryKey: ["CoinHistory", coinId],
  queryFn: () => fetchCoinHistory(coinId!),
  enabled: Boolean(coinId),
});
