import { queryCoinHistory } from "../api";
import { useQuery } from "@tanstack/react-query";
import { useOutletContext } from "react-router-dom";
import ApexChart from "react-apexcharts";
import { useAtomValue } from "jotai";
import { themeState } from "../atoms";

interface ICoinContext {
  coinId: string;
  coinName: string;
}

function Chart() {
  const { coinId } = useOutletContext<ICoinContext>();
  const { isLoading, data } = useQuery(queryCoinHistory(coinId));
  const isDataArray = Array.isArray(data);
  const themeMode = useAtomValue(themeState);

  return (
    <div>
      {isLoading ? (
        "Loading chart..."
      ) : isDataArray ? (
        <ApexChart
          type="candlestick"
          series={[
            {
              data: data.map((price) => ({
                x: new Date(price.time_close),
                y: [
                  Number(price.open),
                  Number(price.high),
                  Number(price.low),
                  Number(price.close),
                ],
              })),
            },
          ]}
          options={{
            theme: {
              mode: themeMode,
            },
            chart: {
              height: 300,
              width: 500,
              toolbar: {
                show: false,
              },
              background: "transparent",
            },
            grid: { show: false },
            yaxis: {
              show: false,
            },
            xaxis: {
              type: "datetime",
              axisBorder: { show: false },
              axisTicks: { show: false },
              labels: { show: false },
            },
            plotOptions: {
              candlestick: {
                colors: {
                  upward: "#0ea5e9",
                  downward: "#ef4444",
                },
              },
            },
          }}
        />
      ) : (
        "No Data Available"
      )}
    </div>
  );
}

export default Chart;
